/**
 * Method-level cache decorators (TTL + invalidation) for NestJS services.
 * Uses the same Redis/Memcached connection module as typed cache access.
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 *
 * Usage (Redis): inject `RedisCacheConnection`, then either pass `connection` for a
 * shared instance or `getConnection` so each service instance resolves its own client.
 */
import { createHash } from 'node:crypto';
import { Logger } from '@nestjs/common';
import Redis from 'ioredis';
import { RedisCacheConnection } from './connection';

const log = new Logger('CacheDecorators');

const DEFAULT_TTL_SECONDS = 300;
const MAX_INLINE_KEY_LENGTH = 100;

/**
 * Build a cache key from positional arguments and optional sorted named fields
 * (mirrors Python `make_cache_key`: long payloads become an MD5 segment).
 */
export function makeCacheKey(
  prefix: string,
  args: readonly unknown[],
  named?: Readonly<Record<string, unknown>>,
): string {
  const keyParts: string[] = args.map((a) => String(a));
  if (named !== undefined) {
    const keys = Object.keys(named).sort();
    for (const k of keys) {
      keyParts.push(`${k}=${String(named[k])}`);
    }
  }
  let keyString = keyParts.join(':');
  if (keyString.length > MAX_INLINE_KEY_LENGTH) {
    keyString = createHash('md5').update(keyString, 'utf8').digest('hex');
  }
  return `${prefix}:${keyString}`;
}

export interface CachedMethodOptions {
  /** Use when the connection is shared (e.g. one provider per module). */
  connection?: RedisCacheConnection;
  /** Use with `@Injectable()` services: return `this.redis` (or similar). */
  getConnection?: (this: unknown) => RedisCacheConnection;
  ttlSeconds?: number;
  keyPrefix?: string;
}

function resolveRedisConnection(
  context: unknown,
  options: CachedMethodOptions,
): RedisCacheConnection {
  if (options.getConnection !== undefined && options.connection !== undefined) {
    throw new Error(
      'CachedMethod options must set exactly one of connection or getConnection, not both',
    );
  }
  if (options.getConnection !== undefined) {
    return options.getConnection.call(context);
  }
  if (options.connection !== undefined) {
    return options.connection;
  }
  throw new Error(
    'CachedMethod requires connection or getConnection (RedisCacheConnection). Available: set connection, or getConnection for per-instance injection',
  );
}

/**
 * Decorator factory: cache async method return values in Redis (JSON) with TTL.
 */
export function CachedMethod(options: CachedMethodOptions): MethodDecorator {
  const ttlSeconds = options.ttlSeconds ?? DEFAULT_TTL_SECONDS;
  return (target: object, propertyKey: string | symbol, descriptor: PropertyDescriptor) => {
    const original = descriptor.value;
    if (typeof original !== 'function') {
      const name = String(propertyKey);
      throw new Error(
        `CachedMethod applies only to methods; property ${name} is not a function`,
      );
    }
    const defaultPrefix = options.keyPrefix ?? String(propertyKey);
    descriptor.value = async function (
      this: unknown,
      ...args: unknown[]
    ): Promise<unknown> {
      const conn = resolveRedisConnection(this, options);
      const client: Redis = conn.getClient();
      const cacheKey = makeCacheKey(defaultPrefix, args);
      try {
        const cachedValue = await client.get(cacheKey);
        if (cachedValue !== null && cachedValue !== undefined) {
          return JSON.parse(cachedValue) as unknown;
        }
      } catch (err: unknown) {
        log.debug(
          `cache_read_failed key=${cacheKey} error=${err instanceof Error ? err.message : String(err)}`,
        );
      }
      const result: unknown = await original.apply(this, args);
      if (result !== null && result !== undefined) {
        try {
          await client.setex(cacheKey, ttlSeconds, JSON.stringify(result));
        } catch (err: unknown) {
          log.debug(
            `cache_write_failed key=${cacheKey} error=${err instanceof Error ? err.message : String(err)}`,
          );
        }
      }
      return result;
    };
    return descriptor;
  };
}

export interface InvalidateCacheAfterOptions {
  connection?: RedisCacheConnection;
  getConnection?: (this: unknown) => RedisCacheConnection;
  /** Glob-style pattern passed to Redis SCAN (e.g. `sessions:*`). */
  pattern: string;
}

function resolveRedisForInvalidate(
  context: unknown,
  options: InvalidateCacheAfterOptions,
): RedisCacheConnection {
  if (options.getConnection !== undefined && options.connection !== undefined) {
    throw new Error(
      'InvalidateCacheAfter options must set exactly one of connection or getConnection, not both',
    );
  }
  if (options.getConnection !== undefined) {
    return options.getConnection.call(context);
  }
  if (options.connection !== undefined) {
    return options.connection;
  }
  throw new Error(
    'InvalidateCacheAfter requires connection or getConnection (RedisCacheConnection). Available: set connection, or getConnection for per-instance injection',
  );
}

async function deleteKeysMatchingPattern(client: Redis, pattern: string): Promise<void> {
  let cursor = '0';
  do {
    const reply = await client.scan(cursor, 'MATCH', pattern, 'COUNT', 100);
    cursor = reply[0];
    const keys = reply[1];
    if (keys.length > 0) {
      await client.del(...keys);
    }
  } while (cursor !== '0');
}

/**
 * After the method runs, delete all keys matching `pattern` (SCAN + DEL).
 */
export function InvalidateCacheAfter(options: InvalidateCacheAfterOptions): MethodDecorator {
  const { pattern } = options;
  return (target: object, propertyKey: string | symbol, descriptor: PropertyDescriptor) => {
    const original = descriptor.value;
    if (typeof original !== 'function') {
      const name = String(propertyKey);
      throw new Error(
        `InvalidateCacheAfter applies only to methods; property ${name} is not a function`,
      );
    }
    descriptor.value = async function (this: unknown, ...args: unknown[]): Promise<unknown> {
      const result: unknown = await original.apply(this, args);
      const conn = resolveRedisForInvalidate(this, options);
      const client = conn.getClient();
      try {
        await deleteKeysMatchingPattern(client, pattern);
      } catch (err: unknown) {
        log.debug(
          `cache_invalidation_failed pattern=${pattern} error=${err instanceof Error ? err.message : String(err)}`,
        );
      }
      return result;
    };
    return descriptor;
  };
}
